'use client';
import { useEffect, useState } from 'react';
import { getSuperAdminToken, getAuthRole, api, Transaction } from '@/lib/api';
import { formatRupiah } from '@/utils/formatters';
export default function TransactionsPage(){const [rows,setRows]=useState<Transaction[]>([]);const [ready,setReady]=useState(false);useEffect(()=>{if(getAuthRole()!=='SUPER_ADMIN'){location.href='/super-admin';return}setReady(true);api.getTransactions().then(setRows).catch(()=>setRows([]))},[]);if(!ready)return <div className="loading">Memeriksa akses…</div>;return <div><div className="page-header"><div><div className="eyebrow">Read Only Ledger</div><h1>Transaksi</h1><p className="subtitle">Tidak ada tombol aksi di halaman transaksi. Edit/hapus hanya dari Super Admin.</p></div></div><section className="section"><div className="table-wrap"><table><thead><tr><th>ID</th><th>Tanggal</th><th>Tipe</th><th>Nama</th><th>Kategori</th><th>Nominal</th></tr></thead><tbody>{rows.map(t=><tr key={t.transaction_id}><td>{t.transaction_id}</td><td>{t.tanggal} {t.jam}</td><td>{t.type}</td><td>{String(t.nama_transaksi||t.nama_pengeluaran)}</td><td>{t.kategori}</td><td>{formatRupiah(t.nominal)}</td></tr>)}{!rows.length&&<tr><td colSpan={6} className="empty muted">Belum ada transaksi.</td></tr>}</tbody></table></div></section></div>}
